import React, { useEffect } from 'react';
import { Link } from 'react-router-dom';
import './LandingPage.css';

function LandingPage() {
    useEffect(() => {
        document.title = "Landing Page";
    }, []);

    return (
        <div className="landing-page">
            <h1 className="landing-page-title">Welcome to Healthy Habits</h1>
            <h2 className="landing-page-subtitle">Join us and explore the opportunities!</h2>
            <p className="landing-page-text">Please choose an option:</p>
            <Link to="/login" className="landing-page-link">Login</Link>
            <br />
            <Link to="/step1" className="landing-page-link">Register</Link>
        </div>
    );
}

export default LandingPage;
